resolved_seed AS (
    SELECT
        seed.*,
        province.code AS province_code,
        province.name AS province_name,
        commune.name AS commune_name
    FROM user_seed seed
    JOIN administrative_communes commune ON commune.code = seed.commune_code
    JOIN administrative_provinces province ON province.code = commune.province_code
    WHERE province.code = 'HO_CHI_MINH'
)
