INSERT INTO tutors (id, user_id, bio, education, experience_years, verification_status, status, created_at, updated_at)
SELECT seed.tutor_id, app_user.id, seed.bio, seed.education, seed.experience_years, 'APPROVED', 'APPROVED', TIMESTAMP '2026-08-10 09:00:00', CURRENT_TIMESTAMP
FROM tutor_seed seed
JOIN users app_user ON LOWER(app_user.email) = seed.email
ON CONFLICT (user_id) DO UPDATE SET
    bio = EXCLUDED.bio,
    education = EXCLUDED.education,
    experience_years = EXCLUDED.experience_years,
    verification_status = 'APPROVED',
    status = 'APPROVED',
    updated_at = CURRENT_TIMESTAMP;

WITH tutor_profiles_seed AS (
    SELECT tutor.id AS tutor_id, tutor.user_id, tutor.bio
    FROM tutors tutor
    JOIN users app_user ON app_user.id = tutor.user_id
    WHERE LOWER(app_user.email) BETWEEN 'tutor1@gmail.com' AND 'tutor9@gmail.com'
       OR LOWER(app_user.email) LIKE 'tutor1%@gmail.com'
       OR LOWER(app_user.email) LIKE 'tutor2%@gmail.com'
       OR LOWER(app_user.email) LIKE 'tutor30@gmail.com'
)
INSERT INTO tutor_profiles (id, user_id, active, bio, created_at, updated_at)
SELECT tutor_id, user_id, TRUE, bio, TIMESTAMP '2026-08-10 09:00:00', CURRENT_TIMESTAMP
FROM tutor_profiles_seed
ON CONFLICT (user_id) DO UPDATE SET
    active = TRUE,
    bio = EXCLUDED.bio,
    updated_at = CURRENT_TIMESTAMP;

