INSERT INTO tutor_applications (
    user_id, status, bio, education_level, institution, major, experience_summary,
    submitted_at, reviewed_at, reviewed_by, review_note,
    applicant_full_name, applicant_email, applicant_phone, applicant_date_of_birth, applicant_gender,
    applicant_province_code, applicant_province_name, applicant_commune_code, applicant_commune_name,
    applicant_address_detail, applicant_avatar_key, created_at, updated_at
)
SELECT
    app_user.id,
    'APPROVED',
    seed.bio,
    seed.education_level,
    seed.institution,
    seed.major,
    seed.experience_summary,
    seed.submitted_at,
    seed.reviewed_at,
    (SELECT id FROM reviewer),
    'Approved development dataset tutor profile.',
    app_user.full_name,
    app_user.email,
    app_user.phone,
    app_user.date_of_birth,
    app_user.gender,
    app_user.province_code,
    app_user.province,
    app_user.commune_code,
    app_user.commune,
    app_user.address_detail,
    app_user.avatar_key,
    seed.submitted_at,
    CURRENT_TIMESTAMP
FROM application_seed seed
JOIN users app_user ON LOWER(app_user.email) = seed.email
ON CONFLICT (user_id) DO UPDATE SET
    status = 'APPROVED',
    bio = EXCLUDED.bio,
    education_level = EXCLUDED.education_level,
    institution = EXCLUDED.institution,
    major = EXCLUDED.major,
    experience_summary = EXCLUDED.experience_summary,
    submitted_at = EXCLUDED.submitted_at,
    reviewed_at = EXCLUDED.reviewed_at,
    reviewed_by = EXCLUDED.reviewed_by,
    review_note = EXCLUDED.review_note,
    applicant_full_name = EXCLUDED.applicant_full_name,
    applicant_email = EXCLUDED.applicant_email,
    applicant_phone = EXCLUDED.applicant_phone,
    applicant_date_of_birth = EXCLUDED.applicant_date_of_birth,
    applicant_gender = EXCLUDED.applicant_gender,
    applicant_province_code = EXCLUDED.applicant_province_code,
    applicant_province_name = EXCLUDED.applicant_province_name,
    applicant_commune_code = EXCLUDED.applicant_commune_code,
    applicant_commune_name = EXCLUDED.applicant_commune_name,
    applicant_address_detail = EXCLUDED.applicant_address_detail,
    applicant_avatar_key = EXCLUDED.applicant_avatar_key,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO tutor_application_teaching_modes (tutor_application_id, teaching_mode)
SELECT app.id, mode
FROM tutor_applications app
JOIN users app_user ON app.user_id = app_user.id
CROSS JOIN (VALUES ('ONLINE'), ('OFFLINE')) AS modes(mode)
WHERE LOWER(app_user.email) IN (
    'tutor1@gmail.com', 'tutor2@gmail.com', 'tutor3@gmail.com', 'tutor4@gmail.com', 'tutor5@gmail.com',
    'tutor6@gmail.com', 'tutor7@gmail.com', 'tutor8@gmail.com', 'tutor9@gmail.com', 'tutor10@gmail.com',
    'tutor11@gmail.com', 'tutor12@gmail.com', 'tutor13@gmail.com', 'tutor14@gmail.com', 'tutor15@gmail.com',
    'tutor16@gmail.com', 'tutor17@gmail.com', 'tutor18@gmail.com', 'tutor19@gmail.com', 'tutor20@gmail.com',
    'tutor21@gmail.com', 'tutor22@gmail.com', 'tutor23@gmail.com', 'tutor24@gmail.com', 'tutor25@gmail.com',
    'tutor26@gmail.com', 'tutor27@gmail.com', 'tutor28@gmail.com', 'tutor29@gmail.com', 'tutor30@gmail.com'
)
ON CONFLICT (tutor_application_id, teaching_mode) DO NOTHING;

