inserted_subjects AS (
    INSERT INTO tutor_application_subjects (
        tutor_application_id, subject_id, subject_name, subject_category_name, subject_group_name,
        one_to_one_hourly_rate, experience_years, description, created_at, updated_at
    )
    SELECT app.id, seed.legacy_subject_id, seed.subject_name, seed.category_name, seed.group_name,
           seed.rate, seed.experience_years, seed.description, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM app_subject_seed seed
    JOIN users app_user ON LOWER(app_user.email) = seed.email
    JOIN tutor_applications app ON app.user_id = app_user.id
    ON CONFLICT (tutor_application_id, subject_id) DO UPDATE SET
        subject_name = EXCLUDED.subject_name,
        subject_category_name = EXCLUDED.subject_category_name,
        subject_group_name = EXCLUDED.subject_group_name,
        one_to_one_hourly_rate = EXCLUDED.one_to_one_hourly_rate,
        experience_years = EXCLUDED.experience_years,
        description = EXCLUDED.description,
        updated_at = CURRENT_TIMESTAMP
    RETURNING id, subject_id
)
INSERT INTO tutor_application_subject_levels (tutor_application_subject_id, level)
SELECT inserted_subjects.id,
       CASE
           WHEN inserted_subjects.subject_id IN (1, 13, 20, 21) THEN 'UPPER_SECONDARY'
           WHEN inserted_subjects.subject_id IN (3, 4) THEN 'EXAM_PREPARATION'
           ELSE 'UNIVERSITY'
       END
FROM inserted_subjects
ON CONFLICT (tutor_application_subject_id, level) DO NOTHING;

SELECT setval('users_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM users), nextval('users_id_seq')), TRUE);
SELECT setval('students_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM students), nextval('students_id_seq')), TRUE);
SELECT setval('tutors_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM tutors), nextval('tutors_id_seq')), TRUE);
SELECT setval('tutor_profiles_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM tutor_profiles), nextval('tutor_profiles_id_seq')), TRUE);
SELECT setval('tutor_applications_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM tutor_applications), nextval('tutor_applications_id_seq')), TRUE);
SELECT setval('tutor_application_subjects_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM tutor_application_subjects), nextval('tutor_application_subjects_id_seq')), TRUE);
